const items = $input.all();

const seen = new Set();
const results = [];

for (const item of items) {
  const data = item.json;

  const event = {
    title: data.name || '',
    date: data.startDate || '',
    time: data.startTime
      ? `${data.startTime}${data.endTime ? ` - ${data.endTime}` : ''}`
      : '',
    venue: data.venue || '',
    city: data.locality || '',
    organiser: data.organizerName || '',
    description: data.description || data.summary || '',
    source_url: data.url || data.sourceUrl || '',
    image_url: data.image || ''
  };

  // Unique event key
  const eventKey = `${event.title}|${event.date}|${event.venue}|${event.source_url}`;

  if (!seen.has(eventKey)) {
    seen.add(eventKey);
    results.push({ json: event });
  }
}

return results;

