const githubData = $input.first().json;

// Decode the existing events.json from GitHub
const existingContent = Buffer
  .from(githubData.content, 'base64')
  .toString('utf8');

const existingData = JSON.parse(existingContent);

// Get the newly approved event
const newEvent = $('Prepare Website Event').first().json;

// Make sure organizer is an object
if (typeof newEvent.organizer === 'string') {
  try {
    newEvent.organizer = JSON.parse(newEvent.organizer);
  } catch {
    newEvent.organizer = {
      name: newEvent.organizer,
      avatar: '',
      verified: false
    };
  }
}

// Convert event time range to start time only
if (newEvent.eventTime && newEvent.eventTime.includes(' - ')) {
  newEvent.eventTime = newEvent.eventTime.split(' - ')[0];
}

// Check if this event already exists
const existingIndex = existingData.events.findIndex(
  event => event.id === newEvent.id
);

if (existingIndex !== -1) {
  // Update existing event
  existingData.events[existingIndex] = {
    ...existingData.events[existingIndex],
    ...newEvent
  };
} else {
  // Add new event at the top
  existingData.events.unshift(newEvent);
}

// Create final JSON content
const updatedContent = JSON.stringify(existingData, null, 2);

return [
  {
    json: {
      ...githubData,
      content: updatedContent
    }
  }
];

